  ($json${"id":3,"name":"Campania Felix: Arte, Storia e Reggia","photos":["https://travelimages.com/campania/napoli-overview.jpg"],"short_desc":"Un viaggio di tre giorni tra la vivacità di Napoli, l'antica Pompei e lo splendore di Caserta.","desc":"Scopri i misteri e la storia millenaria di Napoli, cammina tra le rovine di Pompei e lasciati meravigliare dalla magnificenza della Reggia di Caserta.","duration":3,"days":[{"subtitle":"Giorno 1: Il Cuore di Napoli","places":[{"name":"Napoli - Centro Storico","photos":["https://travelimages.com/napoli/spaccanapoli-street.jpg"],"coordinates":{"lat":40.851778,"lng":14.268124},"events":[{"name":"Museo Cappella Sansevero","desc":"Visita per ammirare il 'Cristo Velato' di Sammartino.","link":{"label":"Biglietti Ufficiali","url":"https://www.museosansevero.it/"},"category":"museum","coordinates":{"lat":40.850722,"lng":14.256247},"price":10,"photos":["https://travelimages.com/napoli/cristo-velato-interno.jpg"],"moments":[{"name":"Cristo Velato","desc":"L'opera scultorea più celebre."}]},{"name":"Pizzeria Sorbillo","desc":"Assaggio della vera pizza napoletana in una delle pizzerie storiche.","category":"food","coordinates":{"lat":40.8519,"lng":14.257},"price":15,"photos":["https://travelimages.com/napoli/pizza-sorbillo.jpg","https://travelimages.com/napoli/sorbillo-esterno.jpg"],"moments":[{"name":"Pizza Margherita","desc":"Il classico intramontabile.","price":6.5},{"name":"Pizza Marinara","desc":"Semplice e saporita.","price":5}]}]}]},{"subtitle":"Giorno 2: Storia Antica e Viste Mozzafiato","places":[{"name":"Pompei - Scavi Archeologici","photos":["https://travelimages.com/pompei/foro-vesuvio.jpg"],"coordinates":{"lat":40.74868,"lng":14.48206},"events":[{"name":"Visita agli Scavi","desc":"Esplorazione del Foro, delle Domus e dei Teatri dell'antica città romana.","link":{"label":"Guida Ufficiale","url":"https://pompeiisites.org/"},"category":"museum","coordinates":{"lat":40.7513,"lng":14.4849},"price":16,"photos":["https://travel